entradas.ejemplo:
Object.fromEntries([["a", 1], ["b", 2]]); // { a: 1, b: 2 }
const precios = { pan: 1, leche: 4 };
Object.fromEntries(Object.entries(precios).map(([k, v]) => [k, v * 2])); // { pan: 2, leche: 8 }
Object.fromEntries(new Map([["x", 1]])); // { x: 1 }

const destino = { a: 1 };
Object.assign(destino, { b: 2 }, { a: 9 }); // { a: 9, b: 2 }
destino; // { a: 9, b: 2 } (cambió)
const copia = Object.assign({}, destino);
copia === destino; // false

const config = Object.freeze({ tema: "oscuro", extra: { x: 1 } });
config.tema = "claro";
config.tema; // "oscuro" (no cambió)
config.extra.x = 2;
config.extra.x; // 2 (lo interno sí cambia)

const base = { a: 1, b: 2 };
({ ...base, b: 3 }); // { a: 1, b: 3 }
({ b: 3, ...base }); // { a: 1, b: 2 }
const user = { dir: { ciudad: "Lima" } };
const copia = { ...user }; copia.dir.ciudad = "Cusco";
user.dir.ciudad; // "Cusco" (copia superficial)

const user = { nombre: "Ana", edad: 20, dir: { ciudad: "Lima" } };
const { nombre, edad } = user; // nombre = "Ana", edad = 20
const { nombre: n, rol = "alumno" } = user; // n = "Ana", rol = "alumno"
const { dir: { ciudad } } = user; // ciudad = "Lima"
const { dir, ...resto } = user; // resto = { nombre: "Ana", edad: 20 }

